    order_ids = [o["id"] for o in orders]
    items = db.query_in("line_items", "order_id", order_ids)
    items_by_order = defaultdict(list)
    for item in items:
        items_by_order[item["order_id"]].append(item)
    for order in orders:
        order["line_items"] = items_by_order.get(order["id"], [])

